ALTER TABLE "games" ADD COLUMN "release_precision" text;--> statement-breakpoint
ALTER TABLE "games" ADD CONSTRAINT "games_release_precision" CHECK ("games"."release_precision" in ('day', 'month', 'year', 'quarter', 'tbd'));--> statement-breakpoint
UPDATE "collections" SET "hidden_columns" = (SELECT coalesce(jsonb_agg(CASE WHEN "e"."v" = 'year' THEN 'released' ELSE "e"."v" END ORDER BY "e"."i"), '[]'::jsonb) FROM jsonb_array_elements_text("collections"."hidden_columns") WITH ORDINALITY AS "e"("v", "i")) WHERE "hidden_columns" @> '["year"]'::jsonb;--> statement-breakpoint
UPDATE "users" SET "list_columns" = (SELECT jsonb_object_agg("l"."key", (SELECT coalesce(jsonb_agg(CASE WHEN "e"."v" = 'year' THEN 'released' ELSE "e"."v" END ORDER BY "e"."i"), '[]'::jsonb) FROM jsonb_array_elements_text("l"."value") WITH ORDINALITY AS "e"("v", "i"))) FROM jsonb_each("users"."list_columns") AS "l") WHERE "list_columns" -> 'owned' @> '["year"]'::jsonb OR "list_columns" -> 'wishlist' @> '["year"]'::jsonb;
